function filterFAQs(){const query=(document.getElementById('faqSearch')?.value||'').trim().toLowerCase(), category=document.querySelector('[data-faq-category].active')?.dataset.faqCategory||'all';let total=0;document.querySelectorAll('[data-faq-group]').forEach(group=>{let visible=0;group.querySelectorAll('[data-faq-item]').forEach(item=>{const match=(category==='all'||group.dataset.faqGroup===category)&&item.dataset.faqItem.includes(query);item.hidden=!match;if(match)visible++});group.hidden=!visible;total+=visible});const count=document.getElementById('faqCount');if(count)count.textContent=`${total} ${total===1?'question':'questions'}`;const empty=document.getElementById('faqEmpty');if(empty)empty.hidden=total>0}

function selectPlan(tile){const plan=listedPlans[Number(tile.dataset.planIndex)];document.querySelectorAll('[data-plan-index]').forEach(item=>item.setAttribute('aria-pressed',String(item===tile)));document.getElementById('planDetailTitle').textContent=plan.name;document.getElementById('planDetailText').textContent=plan.note;document.getElementById('planDetailCompany').textContent=plan.company;document.getElementById('planDetailLink').href=plan.website;const panel=document.getElementById('planDetail');panel.classList.remove('detail-refresh');void panel.offsetWidth;panel.classList.add('detail-refresh')}
document.addEventListener('click',e=>{const tile=e.target.closest('[data-plan-index]');if(tile)selectPlan(tile)});

function initStoryScroll(){
  const root=document.querySelector('[data-story-scroll]');
  if(!root||root.dataset.ready)return;
  root.dataset.ready='1';
  const chapters=[...root.querySelectorAll('.story-chapter')];
  const imgs=[...root.querySelectorAll('.story-scroll-img')];
  const count=root.querySelector('.story-scroll-count');
  const setActive=i=>{
    chapters.forEach((c,k)=>c.classList.toggle('is-active',k===i));
    imgs.forEach((m,k)=>m.classList.toggle('is-active',k===i));
    if(count)count.textContent='0'+(i+1)+' / 0'+chapters.length;
  };
  root.classList.add('is-ready');
  if('IntersectionObserver' in window){
    const io=new IntersectionObserver(entries=>{
      entries.forEach(e=>{if(e.isIntersecting)setActive(chapters.indexOf(e.target))});
    },{rootMargin:'-42% 0px -42% 0px'});
    chapters.forEach(c=>io.observe(c));
  }
  let queued=false;
  const progress=()=>{
    queued=false;
    if(!root.isConnected){window.removeEventListener('scroll',onScroll);return}
    const r=root.getBoundingClientRect();
    const p=Math.min(1,Math.max(0,(window.innerHeight*0.5-r.top)/r.height));
    root.style.setProperty('--p',p.toFixed(3));
  };
  const onScroll=()=>{if(!queued){queued=true;requestAnimationFrame(progress)}};
  window.addEventListener('scroll',onScroll,{passive:true});
  progress();
}
new MutationObserver(initStoryScroll).observe(document.getElementById('app'),{childList:true});
initStoryScroll();

function initEcg(){
  const root=document.querySelector('.about-ecg');
  if(!root||root.dataset.ready)return;
  root.dataset.ready='1';
  const live=root.querySelector('.ecg-live');
  const head=root.querySelector('.ecg-head');
  const steps=[...root.querySelectorAll('.ecg-step')];
  const dots=[...root.querySelectorAll('.ecg-dot')];
  const nodeX=[192,592,992];
  const len=live.getTotalLength();
  const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const draw=p=>{
    live.style.strokeDashoffset=String(len*(1-p));
    const pt=live.getPointAtLength(len*p);
    head.setAttribute('cx',pt.x);head.setAttribute('cy',pt.y);
    head.style.opacity=(p>0.002&&p<0.998)?'1':'0';
    steps.forEach((el,i)=>{const on=pt.x>=nodeX[i]-24||p>=0.999;el.classList.toggle('is-lit',on);dots[i].classList.toggle('is-lit',on)});
  };
  live.style.strokeDasharray=String(len);
  if(reduced){draw(1);return}
  root.classList.add('is-ready');
  let target=0,cur=0,running=false;
  const aim=()=>{
    if(!root.isConnected){window.removeEventListener('scroll',aim);return}
    const r=root.getBoundingClientRect();
    target=Math.min(1,Math.max(0,(window.innerHeight*0.9-r.top)/(r.height*1.3)));
    if(!running){running=true;requestAnimationFrame(tick)}
  };
  const tick=()=>{
    cur+=(target-cur)*0.055;
    if(Math.abs(target-cur)<0.001)cur=target;
    draw(cur);
    if(cur!==target)requestAnimationFrame(tick);else running=false;
  };
  window.addEventListener('scroll',aim,{passive:true});
  draw(0);aim();
}
new MutationObserver(initEcg).observe(document.getElementById('app'),{childList:true});
initEcg();

/* Contact: tabs, live open status and the weekly hours timeline. */
function initContact(){
  const root=document.querySelector('.contact-restored');
  if(!root||root.dataset.ready)return;
  root.dataset.ready='1';
  const tabs=[...root.querySelectorAll('[data-cx-tab]')];
  const show=key=>tabs.forEach(t=>{const on=t.dataset.cxTab===key;t.classList.toggle('is-active',on);t.setAttribute('aria-selected',on);const p=root.querySelector('#'+t.getAttribute('aria-controls'));p.hidden=!on;p.classList.toggle('is-active',on)});
  tabs.forEach((t,i)=>{t.addEventListener('click',()=>show(t.dataset.cxTab));t.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){const n=tabs[(i+(e.key==='ArrowRight'?1:tabs.length-1))%tabs.length];n.focus();show(n.dataset.cxTab)}})});
  const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Chicago',weekday:'short',hour:'numeric',minute:'numeric',hourCycle:'h23'}).formatToParts(new Date());
  const get=t=>parts.find(p=>p.type===t).value;
  const day=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].indexOf(get('weekday'));
  const mins=(+get('hour'))*60+(+get('minute'));
  const T0=480,SPAN=540;
  const fmt=m=>{const hh=Math.floor(m/60),mm=m%60;return (hh%12||12)+(mm?':'+String(mm).padStart(2,'0'):'')+(hh<12?' AM':' PM')};
  let open=false,label='Closed today · see hours below';
  root.querySelectorAll('.cx-hours li').forEach(li=>{
    const u=li.querySelector('u');
    if(u){const s=+li.dataset.s,e=+li.dataset.e;u.style.left=((s-T0)/SPAN*100)+'%';u.dataset.w=((e-s)/SPAN*100);
      requestAnimationFrame(()=>requestAnimationFrame(()=>{u.style.width=u.dataset.w+'%'}))}
    if(+li.dataset.d===day){
      li.classList.add('is-today');
      if(li.dataset.s){const s=+li.dataset.s,e=+li.dataset.e;
        open=mins>=s&&mins<e;
        label=open?'Open now · until '+fmt(e):(mins<s?'Closed · opens today at '+fmt(s):'Closed now · see hours');
        if(mins>=T0&&mins<=T0+SPAN){const n=document.createElement('em');n.style.left=((mins-T0)/SPAN*100)+'%';n.setAttribute('aria-hidden','true');li.querySelector('i').appendChild(n)}}
    }
  });
  const box=root.querySelector('[data-cx-status]');
  if(box)box.classList.toggle('is-open',open);
  if(box){const t=box.querySelector('[data-cx-status-text]');if(t)t.textContent=label;}
}
new MutationObserver(initContact).observe(document.getElementById('app'),{childList:true});
initContact();
